"""Independent 2009/G3 and 2020/A-D answer attempts."""
import json
from pathlib import Path
ANSWERS=[
('2009/G3','Exact baseline: precompute length-k window repair costs as k-max frequency of a[i]-i. The query equals the sum of minima of every subarray in the window-cost interval [l,r-k+1]. Compute that sum in linear interval time using a monotonic stack of (value,multiplicity), maintaining the sum of minima of subarrays ending at each index. This is O(n log n+sum query lengths) time and O(n) space; it is mathematically exact but may time out at maximum q,n. Retain as a limited attempt, not a full-constraints solution.',r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n,k,q;cin>>n>>k>>q;vector<int>a(n),f(2*n+3),c(n-k+1);for(int i=0;i<n;i++){cin>>a[i];a[i]+=n-i;}multiset<int>s;auto change=[&](int x,int d){if(f[x])s.erase(s.find(f[x]));f[x]+=d;if(f[x])s.insert(f[x]);};for(int i=0;i<n;i++){change(a[i],1);if(i>=k)change(a[i-k],-1);if(i>=k-1)c[i-k+1]=k-*s.rbegin();}while(q--){int l,r;cin>>l>>r;--l;r-=k;vector<pair<int,int>>st;ll cur=0,ans=0;for(int i=l;i<=r;i++){int count=1;while(!st.empty()&&st.back().first>=c[i]){cur-=1LL*st.back().first*st.back().second;count+=st.back().second;st.pop_back();}st.push_back({c[i],count});cur+=1LL*c[i]*count;ans+=cur;}cout<<ans<<'\n';}}}'''),
('2020/A','For k>1 the minimum number is the digit sum in base k: each operation removes one base-k unit, and any k equal powers can be consolidated into the next power to reduce the count. Repeated division extracts digits. For k=1 every operation subtracts one, so answer n. O(log_k n) time, O(1) space.',r'''#include <bits/stdc++.h>
using namespace std;int main(){int t;cin>>t;while(t--){long long n,k;cin>>n>>k;if(k==1){cout<<n<<'\n';continue;}long long ans=0;while(n){ans+=n%k;n/=k;}cout<<ans<<'\n';}}'''),
('2020/B','A bulb is toggled once per divisor and therefore remains on iff it is not a perfect square. There are n-floor(sqrt(n)) on bulbs. Binary-search the first n with this count at least k; the count increments by at most one, so equality is guaranteed. Compute integer square roots with long double initial estimate and exact corrected products using division. O(log k) time per case, O(1) space.',r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;ll isqrt(ll n){ll r=sqrtl((long double)n);while(r+1<=n/(r+1))++r;while(r>n/r)--r;return r;}int main(){int t;cin>>t;while(t--){ll k;cin>>k;ll lo=1,hi=2000000000000000000LL;while(lo<hi){ll mid=lo+(hi-lo)/2;if(mid-isqrt(mid)>=k)hi=mid;else lo=mid+1;}cout<<lo<<'\n';}}'''),
('2020/C','The bits of (a&c) are a subset of (a|b), so subtraction clears those bits without borrowing. Solve each bit independently by trying a_bit=0 then 1 and matching (a_bit|b_bit)-(a_bit&c_bit) to d_bit. If neither works output -1. Choosing zero when possible minimizes a; verify the final equation and bound. O(61) time and O(1) space.',r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){ll b,c,d,a=0;cin>>b>>c>>d;bool ok=true;for(int i=0;i<=60;i++){int B=(b>>i)&1,C=(c>>i)&1,D=(d>>i)&1;if(B==D)continue;if((1-C)==D)a|=1LL<<i;else ok=false;}if(!ok||((a|b)-(a&c))!=d||a>(1LL<<61))cout<<-1;else cout<<a;cout<<'\n';}}'''),
('2020/D','For each step d and start a record the maximum endpoint a+k*d. Sweep every residue class modulo each d=1..10, maintaining the furthest active endpoint. If next point i+d is within this endpoint, unite i and i+d in DSU. These adjacent progression edges generate exactly the same components as each original clique. Overlapping intervals can be coalesced by maximum reach. O(m+10n alpha(n)) time, O(10n) space.',r'''#include <bits/stdc++.h>
using namespace std;struct DSU{vector<int>p,s;int count;DSU(int n):p(n+1),s(n+1,1),count(n){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a==b)return;if(s[a]<s[b])swap(a,b);p[b]=a;s[a]+=s[b];--count;}};int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n,m;cin>>n>>m;vector<vector<int>>end(11,vector<int>(n+1));for(int i=0,a,d,k;i<m;i++){cin>>a>>d>>k;end[d][a]=max(end[d][a],a+d*k);}DSU ds(n);for(int d=1;d<=10;d++)for(int r=1;r<=d;r++){int reach=0;for(int i=r;i<=n;i+=d){reach=max(reach,end[d][i]);if(i+d<=reach)ds.join(i,i+d);}}cout<<ds.count<<'\n';}}''')]
if __name__=='__main__':
    p=Path('backend/data/bench/codeforces700_20261116/assistant_answers_v1/shard_test_000_199.jsonl')
    with p.open('a',encoding='utf-8') as out:
        for ident,explanation,code in ANSWERS:
            out.write(json.dumps({'id':ident,'split':'test','author':'current chat assistant','status':'attempted' if ident=='2009/G3' else 'authored','explanation':explanation,'cpp_code':code,'validation':'not executed'})+'\n')
